package com.chattynpcs;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * What any line has to pass, whoever wrote it. The tests hold the bank to these, and
 * GeneratedLinesTest holds the line generator's output to them too.
 */
final class LineRules
{
	static final Pattern BANNED = Pattern.compile("(?i)\\b(bloody|arse|arsed|muppet|just saying|no offence|lovely jubbly|sweet as a nut|on my life|oi oi|pet|duck|petal|ta-ra|telly|radio|lycra|rave|insurance|CV|fiver|tenner|cash|charity shop|stag do|bins|guide|cute|awesome|baddie|pathetic|useless|(mon|tues|wednes|thurs|fri|satur|sun)days?)\\b");

	/**
	 * The tells of a line written by a model rather than said by a person: long dashes, "not just X,
	 * it's Y", and the words models reach for that nobody in Gielinor says
	 */
	static final Pattern AI_TELLS = Pattern.compile("(?i)[—–]|\\bnot (just|only|merely|simply)\\b[^.!?]*,\\s(it's|it is|but|that's)\\b|\\b(testament|tapestry|delv\\w*|resonat\\w*|embark\\w*|unwavering|unparalleled|showcas\\w*|elevat\\w*|vibrant|bustling|intricate|meticulous\\w*|symphony|realm of|in the heart of|a sight to behold)\\b");

	private static final Pattern WORD = Pattern.compile("[A-Za-z][A-Za-z']*");
	private static final Pattern SENTENCE = Pattern.compile("(?<=[.!?])\\s+");
	private static final Pattern INNER_CAPITAL = Pattern.compile("[a-z][A-Z]");

	/**
	 * Lower-case words of every name the game or the reviewed lore list knows
	 */
	private final Set<String> names = new HashSet<>();
	/**
	 * Quest titles that aren't also the name of a place, person or thing: saying "the Grand Tree" is
	 * fine, saying "Monkey Madness" is naming a quest
	 */
	private final List<Pattern> questTitles = new ArrayList<>();

	static LineRules load(ChatterData data) throws IOException
	{
		LineRules rules = new LineRules();
		Set<String> places = new HashSet<>();
		List<String> known = read("wiki_names.txt");
		known.addAll(read("names.txt"));
		for (String name : known)
		{
			rules.addName(name);
			// The Pandemonium is an island, as well as a quest
			places.add(name.toLowerCase(Locale.ROOT).replaceFirst("^the ", ""));
		}
		// Their own words count: if a gnome says it in the game, a gnome can say it here
		for (ChatterData.Speech speech : data.speech)
		{
			if (speech.address != null)
			{
				rules.addName(speech.address.word);
				rules.addName(speech.address.thenWord);
			}
			for (ChatterData.Words words : new ChatterData.Words[]{speech.exclaim, speech.praise, speech.greet, speech.farewell})
			{
				if (words != null)
				{
					words.words.forEach(rules::addName);
				}
			}
			speech.swaps.forEach(swap -> rules.addName(swap.replace));
			speech.evidence.forEach(rules::addName);
			if (speech.babble != null)
			{
				speech.babble.phrases.forEach(rules::addName);
			}
		}
		for (String title : read("quest_titles.txt"))
		{
			// "Dragon Slayer I" is spoken of as "Dragon Slayer"
			String spoken = title.replaceFirst("^The ", "").replaceFirst(" I+$", "");
			if (!places.contains(spoken.toLowerCase(Locale.ROOT)))
			{
				rules.questTitles.add(Pattern.compile("\\b" + Pattern.quote(spoken) + "\\b"));
			}
		}
		return rules;
	}

	private static List<String> read(String file) throws IOException
	{
		List<String> lines = new ArrayList<>();
		try (BufferedReader in = new BufferedReader(new InputStreamReader(LineRules.class.getResourceAsStream(file), StandardCharsets.UTF_8)))
		{
			String line;
			while ((line = in.readLine()) != null)
			{
				// names.txt explains itself in comments
				int comment = line.indexOf('#');
				String name = (comment < 0 ? line : line.substring(0, comment)).trim();
				if (!name.isEmpty())
				{
					lines.add(name);
				}
			}
		}
		return lines;
	}

	private void addName(String name)
	{
		if (name == null)
		{
			return;
		}
		Matcher word = WORD.matcher(name);
		while (word.find())
		{
			names.add(bare(word.group()).toLowerCase(Locale.ROOT));
		}
	}

	/**
	 * The word without its possessive or contraction: "Knights'" is "Knights", "Room'll" is "Room",
	 * "I'm" is "I"
	 */
	private static String bare(String word)
	{
		return word.replaceFirst("'(s|ll|d|re|ve|m)?$", "");
	}

	/**
	 * Words a line capitalises mid-sentence, which no name in the game contains. Each one is either
	 * a name worth checking against the Wiki or one the writer made up.
	 */
	List<String> unknownNames(String line)
	{
		List<String> unknown = new ArrayList<>();
		for (String sentence : SENTENCE.split(line.replaceAll("\\{[a-z_]+}", "x")))
		{
			Matcher word = WORD.matcher(sentence);
			boolean first = true;
			while (word.find())
			{
				String w = bare(word.group());
				boolean name = !first && Character.isUpperCase(w.charAt(0)) || INNER_CAPITAL.matcher(w).find();
				first = false;
				if (!name || w.equals("I"))
				{
					continue;
				}
				String lower = w.toLowerCase(Locale.ROOT);
				// The Fitzharmons are Fitzharmons
				if (!names.contains(lower) && !(lower.endsWith("s") && names.contains(lower.substring(0, lower.length() - 1))))
				{
					unknown.add(w);
				}
			}
		}
		return unknown;
	}

	/**
	 * The quest a line names by its title, or null. Nobody in Gielinor calls their troubles by a
	 * quest's name.
	 */
	String namedQuest(String line)
	{
		for (Pattern title : questTitles)
		{
			if (title.matcher(line).find())
			{
				return title.pattern();
			}
		}
		return null;
	}

	/**
	 * Every line the plugin can say, as {where it lives, the line}
	 */
	static List<String[]> spoken(ChatterData data)
	{
		List<String[]> spoken = new ArrayList<>();
		for (ChatterData.Topic topic : data.topics)
		{
			for (Map.Entry<String, List<String>> entry : topic.lines.entrySet())
			{
				for (String line : entry.getValue())
				{
					spoken.add(new String[]{topic.id + "/" + entry.getKey(), line});
				}
			}
		}
		for (ChatterData.Persona persona : data.personas)
		{
			for (List<String> wrappers : java.util.Arrays.asList(persona.openers, persona.closers, persona.greetings))
			{
				for (String line : wrappers)
				{
					spoken.add(new String[]{persona.id, line.replaceFirst("^[a-z|]+:\\s*", "")});
				}
			}
		}
		for (Map.Entry<String, List<String>> tips : data.slayerTips.entrySet())
		{
			for (String tip : tips.getValue())
			{
				spoken.add(new String[]{"slayer tip for " + tips.getKey(), tip});
			}
		}
		return spoken;
	}
}

package com.chattynpcs;

import com.google.gson.Gson;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Before;
import org.junit.Test;

/**
 * Nobody makes up a person, place or quest. A name the game doesn't have is either one the Wiki
 * knows that belongs in names.txt, or one somebody invented, which is a line to rewrite.
 */
public class LoreTest
{
	private ChatterData data;
	private LineRules rules;

	@Before
	public void before() throws Exception
	{
		data = ChatterData.load(new Gson());
		rules = LineRules.load(data);
	}

	@Test
	public void everyNameIsOneTheGameKnows()
	{
		List<String> unknown = new ArrayList<>();
		for (String[] line : LineRules.spoken(data))
		{
			for (String name : rules.unknownNames(line[1]))
			{
				unknown.add(name + " in " + line[0] + ": " + line[1]);
			}
		}
		assertTrue("Names the game doesn't know. Check each against the Wiki, then add it to names.txt or rewrite the line:\n"
			+ String.join("\n", unknown), unknown.isEmpty());
	}

	@Test
	public void nobodyNamesAQuest()
	{
		List<String> named = new ArrayList<>();
		for (String[] line : LineRules.spoken(data))
		{
			String quest = rules.namedQuest(line[1]);
			if (quest != null)
			{
				named.add(quest + " in " + line[0] + ": " + line[1]);
			}
		}
		assertTrue("Lines that name a quest:\n" + String.join("\n", named), named.isEmpty());
	}

	@Test
	public void theChecksCatchWhatTheyShould()
	{
		assertEquals(Arrays.asList("Glimmerhold"), rules.unknownNames("Fresh from Glimmerhold, are you? In that hat?"));
		assertEquals(Arrays.asList(), rules.unknownNames("The Fitzharmons and the Black Knights' lot. JalYt-Ket, maybe."));
		assertEquals(Arrays.asList(), rules.unknownNames("Well, I'm off, and I'd say I've earned it."));
		assertNotNull(rules.namedQuest("Did you ever finish Monkey Madness, then?"));
		assertNull(rules.namedQuest("Something's eating the Grand Tree, they say."));
		assertNull(rules.namedQuest("Narnode's monkey madness has gone on long enough."));
		assertTrue(LineRules.AI_TELLS.matcher("It's not just a cape, it's a statement.").find());
		assertTrue(LineRules.BANNED.matcher("See you Sundays.").find());
	}

	@Test
	public void noLineSoundsWrittenByAMachine()
	{
		List<String> tells = new ArrayList<>();
		for (String[] line : LineRules.spoken(data))
		{
			if (LineRules.AI_TELLS.matcher(line[1]).find())
			{
				tells.add(line[0] + ": " + line[1]);
			}
		}
		assertTrue("Lines with a machine's tells:\n" + String.join("\n", tells), tells.isEmpty());
	}
}

package com.chattynpcs;

import com.google.gson.Gson;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Paths;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Random;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.api.coords.WorldPoint;
import org.junit.Test;

/**
 * Not a check: writes build/render.tsv, what real speakers in real places actually say to a few
 * kinds of player, with the line as written next to what came out. For reading, the way a player
 * would hear it, to catch lines the pieces don't fit together into. Every test run refreshes it.
 */
public class RenderReport
{
	private static final Object[][] SPEAKERS = {
		{"Hans", "Lumbridge", 3222, 3218}, {"Banker", "Varrock West bank", 3185, 3438}, {"Bartender", "Varrock", 3225, 3400},
		{"Father Aereck", "Lumbridge church", 3243, 3206}, {"Guard", "Falador", 2965, 3380}, {"Shop keeper", "Falador", 2958, 3388},
		{"Gnome", "Gnome Stronghold", 2460, 3440}, {"Gnome child", "Gnome Stronghold", 2465, 3445}, {"Gnome banker", "Grand Tree", 2449, 3482},
		{"TzHaar-Hur-Tel", "Mor Ul Rek", 2480, 5170}, {"Dwarf", "Keldagrim", 2850, 10200}, {"Thurgo", "Port Sarim", 3000, 3145},
		{"Brundt the Chieftain", "Rellekka", 2660, 3680}, {"Man", "Jatizso", 2400, 3810}, {"Man", "Neitiznot", 2335, 3805},
		{"Oneiromancer", "Lunar Isle", 2150, 3870}, {"Rantz", "Feldip Hills", 2630, 2981}, {"Elder Krill", "the Great Conch", 3190, 2420},
		{"Man", "Canifis", 3495, 3490}, {"Ghost villager", "Port Phasmatys", 3680, 3490}, {"Man", "Darkmeyer", 3620, 3360},
		{"Man", "Burgh de Rott", 3502, 3220}, {"Man", "Al Kharid", 3293, 3180}, {"Man", "Pollnivneach", 3359, 2970},
		{"Man", "Sophanem", 3300, 2780}, {"Man", "Shantay Pass", 3300, 3120}, {"Man", "Tai Bwo Wannai", 2790, 3060},
		{"Man", "Civitas illa Fortis", 1680, 3130}, {"Man", "Arceuus", 1680, 3780}, {"Man", "Port Piscarilius", 1810, 3730},
		{"Man", "Shayzien", 1500, 3600}, {"Man", "Lovakengj", 1500, 3800}, {"Man", "the Pandemonium", 3050, 2980},
		{"Elf", "Lletya", 2340, 3170}, {"Monkey", "Ape Atoll", 2770, 2780}, {"Vannaka", "Edgeville", 3145, 9914},
		{"Granny", "Draynor", 3090, 3250}, {"Wizard Mizgog", "Wizards' Tower", 3105, 3160}, {"Pirate", "Brimhaven", 2790, 3170},
		{"Duke Horacio", "Lumbridge Castle", 3210, 3220}, {"Fred the Farmer", "Lumbridge", 3190, 3273}, {"Street urchin", "Varrock", 3215, 3425},
	};

	private static Map<String, CharacterReader.Snapshot> players(LinePicker picker)
	{
		Map<String, CharacterReader.Snapshot> players = new LinkedHashMap<>();

		CharacterReader.Snapshot fresh = new CharacterReader.Snapshot();
		fresh.facts.add("always");
		fresh.facts.add("low_combat");
		fresh.facts.add("skint");
		fresh.facts.add("no_slayer_task");
		fresh.worn.put(EquipmentInventorySlot.BODY, "Bronze platebody");
		fresh.worn.put(EquipmentInventorySlot.LEGS, "Bronze platelegs");
		fresh.worn.put(EquipmentInventorySlot.WEAPON, "Bronze sword");
		for (Quest q : picker.quests())
		{
			fresh.quests.put(q, QuestState.NOT_STARTED);
		}
		players.put("new player", fresh);

		CharacterReader.Snapshot mid = new CharacterReader.Snapshot();
		mid.facts.add("always");
		mid.facts.add("bald");
		mid.facts.add("slayer_task");
		mid.vars.put("task", "hill giants");
		mid.worn.put(EquipmentInventorySlot.HEAD, "Helm of neitiznot");
		mid.worn.put(EquipmentInventorySlot.BODY, "Green d'hide body");
		mid.worn.put(EquipmentInventorySlot.WEAPON, "Rune scimitar");
		mid.worn.put(EquipmentInventorySlot.CAPE, "Fire cape");
		mid.pet = "Rocky";
		int i = 0;
		for (Quest q : picker.quests())
		{
			mid.quests.put(q, i++ % 2 == 0 ? QuestState.FINISHED : QuestState.NOT_STARTED);
		}
		players.put("mid player", mid);

		CharacterReader.Snapshot end = new CharacterReader.Snapshot();
		end.facts.add("always");
		end.facts.add("high_combat");
		end.facts.add("loaded");
		end.facts.add("slayer_task_nearly_done");
		end.facts.add("slayer_task");
		end.vars.put("task", "abyssal demons");
		end.worn.put(EquipmentInventorySlot.HEAD, "Torva full helm");
		end.worn.put(EquipmentInventorySlot.BODY, "Torva platebody");
		end.worn.put(EquipmentInventorySlot.WEAPON, "Twisted bow");
		end.worn.put(EquipmentInventorySlot.CAPE, "Infernal cape");
		end.worn.put(EquipmentInventorySlot.AMULET, "Ghostspeak amulet");
		end.pet = "Olmlet";
		for (Quest q : picker.quests())
		{
			end.quests.put(q, QuestState.FINISHED);
		}
		players.put("endgame player", end);
		return players;
	}

	@Test
	public void render() throws Exception
	{
		ChatterData data = ChatterData.load(new Gson());
		StringBuilder out = new StringBuilder("player\tmood\tspeaker\twhere\tpersona\ttopic\tkey\twritten\tsaid\n");
		ChattyNpcsConfig.Mood[] moods = {ChattyNpcsConfig.Mood.BALANCED, ChattyNpcsConfig.Mood.BALANCED, ChattyNpcsConfig.Mood.KIND, ChattyNpcsConfig.Mood.RUDE};
		int seed = 0;
		for (Object[] speaker : SPEAKERS)
		{
			LinePicker picker = new LinePicker(data, new Random(seed++));
			for (Map.Entry<String, CharacterReader.Snapshot> player : players(picker).entrySet())
			{
				long now = 0;
				for (ChattyNpcsConfig.Mood mood : moods)
				{
					for (int k = 0; k < 4; k++)
					{
						now += 60_000;
						LinePicker.Comment c = picker.pick(player.getValue(), (String) speaker[0], new WorldPoint((int) speaker[2], (int) speaker[3], 0), mood, 300_000, now);
						if (c != null)
						{
							out.append(player.getKey()).append('\t').append(mood).append('\t').append(speaker[0]).append('\t').append(speaker[1]).append('\t')
								.append(c.getPersona()).append('\t').append(c.getTopicId()).append('\t').append(c.getKey()).append('\t')
								.append(c.getWritten()).append('\t').append(c.getText()).append('\n');
						}
					}
				}
			}
		}
		Files.write(Paths.get("build/render.tsv"), out.toString().getBytes(StandardCharsets.UTF_8));
	}
}
